import { Module } from "@nestjs/common";
import { InsuranceController } from "./insurance.controller";
import {
  ClaimItemRepository,
  ClaimRepository,
  EligibilityCheckRepository,
  InsuranceProfileRepository,
  InsuranceService,
  PreauthRepository,
  RemittanceRepository,
} from "./insurance.service";
import { IdentityModule } from "../identity/identity.module";
import { AuthModule } from "../auth/auth.module";
import { AuditModule } from "../audit/audit.module";
import { EventsModule } from "../events/events.module";

/**
 * Revenue cycle. Claims are generated by READING invoices through SQL inside
 * the same transaction rather than calling BillingService, so an invoice can
 * never be amended between the snapshot and the claim rows being written —
 * BillingModule is intentionally not imported here.
 */
@Module({
  imports: [IdentityModule, AuthModule, AuditModule, EventsModule],
  controllers: [InsuranceController],
  providers: [
    InsuranceService,
    InsuranceProfileRepository,
    EligibilityCheckRepository,
    PreauthRepository,
    ClaimRepository,
    ClaimItemRepository,
    RemittanceRepository,
  ],
  exports: [InsuranceService, ClaimRepository],
})
export class InsuranceModule {}
